    b[0U] = 0xfffffffffffffffdULL;
    b[1U] = 0xffffffffffffffffULL;
    b[2U] = 0xffffffffffffffffULL;
    b[3U] = 0xffffffffffffffffULL;
    b[4U] = 0xffffffffffffffffULL;
    b[5U] = 0xffffffffffffffffULL;
    b[6U] = 0xffffffffffffffffULL;
    b[7U] = 0xffffffffffffffffULL;
    b[8U] = 0x1ffULL;
    uint64_t tmp[9U] = { 0U };
    memcpy(tmp, a, 9U * sizeof(uint64_t));
    uint64_t table[288U] = { 0U };
    uint64_t tmp1[9U] = { 0U };
    uint64_t *t0 = table;
    uint64_t *t1 = table + 9U;
    p521_make_fone(t0);
    memcpy(t1, tmp, 9U * sizeof(uint64_t));
    KRML_MAYBE_FOR15(i,
                     0U,
                     15U,
                     1U,
                     uint64_t *t11 = table + (i + 1U) * 9U;
                     fsqr0(tmp1, t11);
                     memcpy(table + (2U * i + 2U) * 9U, tmp1, 9U * sizeof(uint64_t));
                     uint64_t *t2 = table + (2U * i + 2U) * 9U;
                     fmul0(tmp1, tmp, t2);
                     memcpy(table + (2U * i + 3U) * 9U, tmp1, 9U * sizeof(uint64_t)););
    uint32_t i0 = 520U;
    uint64_t bits_c = Hacl_Bignum_Lib_bn_get_bits_u64(9U, b, i0, 5U);
    memcpy(res, (uint64_t *)table, 9U * sizeof(uint64_t));
    for (uint32_t i1 = 0U; i1 < 31U; i1++) {
        uint64_t c = FStar_UInt64_eq_mask(bits_c, (uint64_t)(i1 + 1U));
        const uint64_t *res_j = table + (i1 + 1U) * 9U;
        KRML_MAYBE_FOR9(i,
                        0U,
                        9U,
                        1U,
                        uint64_t *os = res;
                        uint64_t x = (c & res_j[i]) | (~c & res[i]);
                        os[i] = x;);
    }
    uint64_t tmp10[9U] = { 0U };
    for (uint32_t i1 = 0U; i1 < 104U; i1++) {
        KRML_MAYBE_FOR5(i, 0U, 5U, 1U, fsqr0(res, res););
        uint32_t k = 520U - 5U * i1 - 5U;
        uint64_t bits_l = Hacl_Bignum_Lib_bn_get_bits_u64(9U, b, k, 5U);
        memcpy(tmp10, (uint64_t *)table, 9U * sizeof(uint64_t));
        for (uint32_t i2 = 0U; i2 < 31U; i2++) {
            uint64_t c = FStar_UInt64_eq_mask(bits_l, (uint64_t)(i2 + 1U));
            const uint64_t *res_j = table + (i2 + 1U) * 9U;
            KRML_MAYBE_FOR9(i,
                            0U,
                            9U,
                            1U,
                            uint64_t *os = tmp10;
                            uint64_t x = (c & res_j[i]) | (~c & tmp10[i]);
                            os[i] = x;);
        }
        fmul0(res, res, tmp10);
    }
}

static SECStatus
prng_getEntropy(PRUint8 *buffer, size_t requestLength)
{
    size_t total = 0;
    PRUint8 block[PRNG_ENTROPY_BLOCK_SIZE];
    PRUint8 hash[SHA256_LENGTH];
    SHA256Context ctx;
    SECStatus rv = SECSuccess;

    if (PR_CallOnce(&coRNGInitEntropy, prng_initEntropy) != PR_SUCCESS) {
        PORT_SetError(SEC_ERROR_LIBRARY_FAILURE);
        return SECFailure;
    }

    /* For FIPS 140-2 4.9.2 continuous random generator test,
     * iteratively fetch fixed sized blocks from the system and
     * compare consecutive blocks. */
    while (total < requestLength) {
        size_t length = RNG_SystemRNG(block, sizeof(block));
        if (length == 0) {
            rv = SECFailure; /* error is already set */
            goto out;
        }
        PORT_Assert(length == sizeof(block));

        /* Store the hash of the entropy block rather than the block
         * itself for backward secrecy. */
        SHA256_Begin(&ctx);
        SHA256_Update(&ctx, block, sizeof(block));
        SHA256_End(&ctx, hash, NULL, sizeof(hash));

        if (PORT_Memcmp(globalrng->previousEntropyHash, hash, sizeof(hash)) == 0) {
            PORT_SetError(SEC_ERROR_LIBRARY_FAILURE);
            rv = SECFailure;
            goto out;
        }
        PORT_Memcpy(globalrng->previousEntropyHash, hash, sizeof(hash));
        length = PR_MIN(requestLength - total, sizeof(block));
        PORT_Memcpy(buffer, block, length);
        total += length;
        buffer += length;
    }

out:
    PORT_Memset(hash, 0, sizeof hash);
    PORT_Memset(block, 0, sizeof block);
    return rv;
}

static CK_RV
sftk_InitCBCMac(CK_SESSION_HANDLE hSession, CK_MECHANISM_PTR pMechanism,
                CK_OBJECT_HANDLE hKey, CK_ATTRIBUTE_TYPE keyUsage,
                SFTKContextType contextType)

{
    CK_MECHANISM cbc_mechanism;
    CK_ULONG mac_bytes = SFTK_INVALID_MAC_SIZE;
#ifndef NSS_DISABLE_DEPRECATED_RC2
    CK_RC2_CBC_PARAMS rc2_params;
#endif
#if NSS_SOFTOKEN_DOES_RC5
    CK_RC5_CBC_PARAMS rc5_params;
    CK_RC5_MAC_GENERAL_PARAMS *rc5_mac;
#endif
    unsigned char ivBlock[SFTK_MAX_BLOCK_SIZE];
    unsigned char k2[SFTK_MAX_BLOCK_SIZE];
    unsigned char k3[SFTK_MAX_BLOCK_SIZE];
    SFTKSession *session;
    SFTKSessionContext *context;
    CK_RV crv;
    unsigned int blockSize;
    PRBool isXCBC = PR_FALSE;

    if (!pMechanism) {
        return CKR_MECHANISM_PARAM_INVALID;
    }

    switch (pMechanism->mechanism) {
#ifndef NSS_DISABLE_DEPRECATED_RC2
        case CKM_RC2_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_RC2_MAC_GENERAL_PARAMS))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes =
                ((CK_RC2_MAC_GENERAL_PARAMS *)pMechanism->pParameter)->ulMacLength;
        /* fall through */
        case CKM_RC2_MAC:
            if (pMechanism->mechanism == CKM_RC2_MAC &&
                BAD_PARAM_CAST(pMechanism, sizeof(CK_RC2_CBC_PARAMS))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            /* this works because ulEffectiveBits is in the same place in both the
             * CK_RC2_MAC_GENERAL_PARAMS and CK_RC2_CBC_PARAMS */
            rc2_params.ulEffectiveBits = ((CK_RC2_MAC_GENERAL_PARAMS *)
                                              pMechanism->pParameter)
                                             ->ulEffectiveBits;
            PORT_Memset(rc2_params.iv, 0, sizeof(rc2_params.iv));
            cbc_mechanism.mechanism = CKM_RC2_CBC;
            cbc_mechanism.pParameter = &rc2_params;
            cbc_mechanism.ulParameterLen = sizeof(rc2_params);
            blockSize = 8;
            break;
#endif /* NSS_DISABLE_DEPRECATED_RC2 */

#if NSS_SOFTOKEN_DOES_RC5
        case CKM_RC5_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_RC5_MAC_GENERAL_PARAMS))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes =
                ((CK_RC5_MAC_GENERAL_PARAMS *)pMechanism->pParameter)->ulMacLength;
        /* fall through */
        case CKM_RC5_MAC:
            /* this works because ulEffectiveBits is in the same place in both the
             * CK_RC5_MAC_GENERAL_PARAMS and CK_RC5_CBC_PARAMS */
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_RC5_MAC_GENERAL_PARAMS))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            rc5_mac = (CK_RC5_MAC_GENERAL_PARAMS *)pMechanism->pParameter;
            rc5_params.ulWordsize = rc5_mac->ulWordsize;
            rc5_params.ulRounds = rc5_mac->ulRounds;
            rc5_params.pIv = ivBlock;
            if ((blockSize = rc5_mac->ulWordsize * 2) > SFTK_MAX_BLOCK_SIZE)
                return CKR_MECHANISM_PARAM_INVALID;
            rc5_params.ulIvLen = blockSize;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_RC5_CBC;
            cbc_mechanism.pParameter = &rc5_params;
            cbc_mechanism.ulParameterLen = sizeof(rc5_params);
            break;
#endif
        /* add cast and idea later */
        case CKM_DES_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_DES_MAC:
            blockSize = 8;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_DES_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
        case CKM_DES3_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_DES3_MAC:
            blockSize = 8;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_DES3_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
        case CKM_CDMF_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_CDMF_MAC:
            blockSize = 8;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_CDMF_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
#ifndef NSS_DISABLE_DEPRECATED_SEED
        case CKM_SEED_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_SEED_MAC:
            blockSize = 16;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_SEED_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
#endif /* NSS_DISABLE_DEPRECATED_SEED */
        case CKM_CAMELLIA_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_CAMELLIA_MAC:
            blockSize = 16;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_CAMELLIA_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
        case CKM_AES_MAC_GENERAL:
            if (BAD_PARAM_CAST(pMechanism, sizeof(CK_ULONG))) {
                return CKR_MECHANISM_PARAM_INVALID;
            }
            mac_bytes = *(CK_ULONG *)pMechanism->pParameter;
        /* fall through */
        case CKM_AES_MAC:
            blockSize = 16;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_AES_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            break;
        case CKM_AES_XCBC_MAC_96:
        case CKM_AES_XCBC_MAC:
            /* The only difference between CKM_AES_XCBC_MAC
             * and CKM_AES_XCBC_MAC_96 is the size of the returned mac. */
            mac_bytes = pMechanism->mechanism == CKM_AES_XCBC_MAC_96 ? 12 : 16;
            blockSize = 16;
            PORT_Memset(ivBlock, 0, blockSize);
            cbc_mechanism.mechanism = CKM_AES_CBC;
            cbc_mechanism.pParameter = &ivBlock;
            cbc_mechanism.ulParameterLen = blockSize;
            /* is XCBC requires extra processing at the end of the operation */
            isXCBC = PR_TRUE;
            /* The input key is used to generate k1, k2, and k3. k2 and k3
             * are used at the end in the pad step. k1 replaces the input
             * key in the aes cbc mac */
            crv = sftk_aes_xcbc_new_keys(hSession, hKey, &hKey, k2, k3);
            if (crv != CKR_OK) {
                return crv;
            }
            break;
        default:
            return CKR_FUNCTION_NOT_SUPPORTED;
    }

    /* if MAC size is externally supplied, it should be checked.
     */
    if (mac_bytes == SFTK_INVALID_MAC_SIZE)
        mac_bytes = blockSize >> 1;
    else {
        if (mac_bytes > blockSize) {
            crv = CKR_MECHANISM_PARAM_INVALID;
            goto fail;
        }
    }

    crv = sftk_CryptInit(hSession, &cbc_mechanism, hKey,
                         CKA_ENCRYPT, /* CBC mech is able to ENCRYPT, not SIGN/VERIFY */
                         keyUsage, contextType, PR_TRUE);
    if (crv != CKR_OK)
        goto fail;
    /* Hold the session reference for the duration of the context writes;
     * see comment on NSC_DigestUpdate. */
    crv = sftk_GetContext(hSession, &context, contextType, PR_TRUE, &session);

    /* this shouldn't happen! */
    PORT_Assert(crv == CKR_OK);
    if (crv != CKR_OK)
        goto fail;
    context->blockSize = blockSize;
    context->macSize = mac_bytes;
    context->isXCBC = isXCBC;
    if (isXCBC) {
        /* save the xcbc specific parameters */
        PORT_Memcpy(context->k2, k2, blockSize);
        PORT_Memcpy(context->k3, k3, blockSize);
        PORT_Memset(k2, 0, blockSize);
        PORT_Memset(k3, 0, blockSize);
        /* get rid of the temp key now that the context has been created */
        NSC_DestroyObject(hSession, hKey);
    }
    sftk_FreeSession(session);
    return CKR_OK;
fail:
    if (isXCBC) {
        PORT_Memset(k2, 0, blockSize);
        PORT_Memset(k3, 0, blockSize);
        NSC_DestroyObject(hSession, hKey); /* get rid of our temp key */
    }
    return crv;
}

static libcrux_ml_kem_utils_extraction_helper_Keypair768
generate_keypair_a2(
    Eurydice_slice key_generation_seed)
{
