void
SHA512_EndRaw(SHA512Context *ctx, unsigned char *digest,
              unsigned int *digestLen, unsigned int maxDigestLen)
{
    PRUint64 h[8];
    unsigned int len;

    memcpy(h, ctx->h, sizeof(h));

#if defined(IS_LITTLE_ENDIAN)
    BYTESWAP8(h[0]);
    BYTESWAP8(h[1]);
    BYTESWAP8(h[2]);
    BYTESWAP8(h[3]);
    BYTESWAP8(h[4]);
    BYTESWAP8(h[5]);
    BYTESWAP8(h[6]);
    BYTESWAP8(h[7]);
#endif
    len = PR_MIN(SHA512_LENGTH, maxDigestLen);
    memcpy(digest, h, len);
    if (digestLen)
        *digestLen = len;
}

void
SEED_cbc_encrypt(const unsigned char *in, unsigned char *out,
                 size_t len, const SEED_KEY_SCHEDULE *ks,
                 unsigned char ivec[SEED_BLOCK_SIZE], int enc)
{
    size_t n;
    unsigned char tmp[SEED_BLOCK_SIZE];
    const unsigned char *iv = ivec;

    if (enc) {
        while (len >= SEED_BLOCK_SIZE) {
            for (n = 0; n < SEED_BLOCK_SIZE; ++n) {
                out[n] = in[n] ^ iv[n];
            }

            SEED_encrypt(out, out, ks);
            iv = out;
            len -= SEED_BLOCK_SIZE;
            in += SEED_BLOCK_SIZE;
            out += SEED_BLOCK_SIZE;
        }

        if (len) {
            for (n = 0; n < len; ++n) {
                out[n] = in[n] ^ iv[n];
            }

            for (n = len; n < SEED_BLOCK_SIZE; ++n) {
                out[n] = iv[n];
            }

            SEED_encrypt(out, out, ks);
            iv = out;
        }

        memcpy(ivec, iv, SEED_BLOCK_SIZE);
    } else if (in != out) {
        while (len >= SEED_BLOCK_SIZE) {
            SEED_decrypt(in, out, ks);

            for (n = 0; n < SEED_BLOCK_SIZE; ++n) {
                out[n] ^= iv[n];
            }

            iv = in;
            len -= SEED_BLOCK_SIZE;
            in += SEED_BLOCK_SIZE;
            out += SEED_BLOCK_SIZE;
        }

        if (len) {
            SEED_decrypt(in, tmp, ks);

            for (n = 0; n < len; ++n) {
                out[n] = tmp[n] ^ iv[n];
            }

            iv = in;
        }

        memcpy(ivec, iv, SEED_BLOCK_SIZE);
    } else {
        while (len >= SEED_BLOCK_SIZE) {
            memcpy(tmp, in, SEED_BLOCK_SIZE);
            SEED_decrypt(in, out, ks);

            for (n = 0; n < SEED_BLOCK_SIZE; ++n) {
                out[n] ^= ivec[n];
            }

            memcpy(ivec, tmp, SEED_BLOCK_SIZE);
            len -= SEED_BLOCK_SIZE;
            in += SEED_BLOCK_SIZE;
            out += SEED_BLOCK_SIZE;
        }

        if (len) {
            memcpy(tmp, in, SEED_BLOCK_SIZE);
            SEED_decrypt(tmp, tmp, ks);

            for (n = 0; n < len; ++n) {
                out[n] = tmp[n] ^ ivec[n];
            }

            memcpy(ivec, tmp, SEED_BLOCK_SIZE);
        }
    }
}

