            /* The input key is used to generate k1, k2, and k3. k2 and k3
             * are used at the end in the pad step. k1 replaces the input
             * key in the aes cbc mac */
            crv = sftk_aes_xcbc_new_keys(hSession, hKey, &hKey, k2, k3);
            if (crv != CKR_OK) {
                return crv;
            }
            break;
        default:
            return CKR_FUNCTION_NOT_SUPPORTED;
    }

    /* if MAC size is externally supplied, it should be checked.
     */
    if (mac_bytes == SFTK_INVALID_MAC_SIZE)
        mac_bytes = blockSize >> 1;
    else {
        if (mac_bytes > blockSize) {
            crv = CKR_MECHANISM_PARAM_INVALID;
            goto fail;
        }
    }

    crv = sftk_CryptInit(hSession, &cbc_mechanism, hKey,
                         CKA_ENCRYPT, /* CBC mech is able to ENCRYPT, not SIGN/VERIFY */
                         keyUsage, contextType, PR_TRUE);
    if (crv != CKR_OK)
        goto fail;
    /* Hold the session reference for the duration of the context writes;
     * see comment on NSC_DigestUpdate. */
    crv = sftk_GetContext(hSession, &context, contextType, PR_TRUE, &session);

    /* this shouldn't happen! */
    PORT_Assert(crv == CKR_OK);
    if (crv != CKR_OK)
        goto fail;
    context->blockSize = blockSize;
    context->macSize = mac_bytes;
    context->isXCBC = isXCBC;
    if (isXCBC) {
        /* save the xcbc specific parameters */
        PORT_Memcpy(context->k2, k2, blockSize);
        PORT_Memcpy(context->k3, k3, blockSize);
        PORT_Memset(k2, 0, blockSize);
        PORT_Memset(k3, 0, blockSize);
        /* get rid of the temp key now that the context has been created */
        NSC_DestroyObject(hSession, hKey);
    }
    sftk_FreeSession(session);
    return CKR_OK;
fail:
    if (isXCBC) {
        PORT_Memset(k2, 0, blockSize);
        PORT_Memset(k3, 0, blockSize);
        NSC_DestroyObject(hSession, hKey); /* get rid of our temp key */
    }
    return crv;
}

static PRStatus
prng_initEntropy(void)
{
    size_t length;
    PRUint8 block[PRNG_ENTROPY_BLOCK_SIZE];
    SHA256Context ctx;

    /* For FIPS 140-2 4.9.2 continuous random number generator test,
     * fetch the initial entropy from the system RNG and keep it for
     * later comparison. */
    length = RNG_SystemRNG(block, sizeof(block));
    if (length == 0) {
        return PR_FAILURE; /* error is already set */
    }
    PORT_Assert(length == sizeof(block));

    /* Store the hash of the entropy block rather than the block
     * itself for backward secrecy. */
    SHA256_Begin(&ctx);
    SHA256_Update(&ctx, block, sizeof(block));
    SHA256_End(&ctx, globalrng->previousEntropyHash, NULL,
               sizeof(globalrng->previousEntropyHash));
    PORT_Memset(block, 0, sizeof(block));
    SHA256_DestroyContext(&ctx, PR_FALSE);
    return PR_SUCCESS;
}

static SECStatus
rsa_HMACPrf(HMACContext *hmac, const char *label, int labelLen,
            int hashLength, unsigned char *output, int length)
{
    unsigned char iterator[2] = { 0, 0 };
    unsigned char encodedLen[2] = { 0, 0 };
    unsigned char hmacLast[HASH_LENGTH_MAX];
    unsigned int left = length;
    unsigned int hashReturn;
    SECStatus rv = SECSuccess;

    /* encodedLen is in bits, length is in bytes, thus the shifts
     * do an implied multiply by 8 */
    encodedLen[0] = (length >> 5) & 0xff;
    encodedLen[1] = (length << 3) & 0xff;

    while (left > hashLength) {
        HMAC_Begin(hmac);
        HMAC_Update(hmac, iterator, 2);
        HMAC_Update(hmac, (const unsigned char *)label, labelLen);
        HMAC_Update(hmac, encodedLen, 2);
        rv = HMAC_Finish(hmac, output, &hashReturn, hashLength);
        if (rv != SECSuccess) {
            return rv;
        }
        iterator[1]++;
        if (iterator[1] == 0)
            iterator[0]++;
        left -= hashLength;
        output += hashLength;
    }
    if (left) {
        HMAC_Begin(hmac);
        HMAC_Update(hmac, iterator, 2);
        HMAC_Update(hmac, (const unsigned char *)label, labelLen);
        HMAC_Update(hmac, encodedLen, 2);
        rv = HMAC_Finish(hmac, hmacLast, &hashReturn, sizeof(hmacLast));
        if (rv != SECSuccess) {
            return rv;
        }
        PORT_Memcpy(output, hmacLast, left);
        PORT_SafeZero(hmacLast, sizeof(hmacLast));
    }
    return rv;
}

static inline void
p521_finv(uint64_t *res, uint64_t *a)
{
    uint64_t b[9U] = { 0U };
    b[0U] = 0xfffffffffffffffdULL;
    b[1U] = 0xffffffffffffffffULL;
    b[2U] = 0xffffffffffffffffULL;
    b[3U] = 0xffffffffffffffffULL;
    b[4U] = 0xffffffffffffffffULL;
    b[5U] = 0xffffffffffffffffULL;
    b[6U] = 0xffffffffffffffffULL;
    b[7U] = 0xffffffffffffffffULL;
    b[8U] = 0x1ffULL;
    uint64_t tmp[9U] = { 0U };
    memcpy(tmp, a, 9U * sizeof(uint64_t));
    uint64_t table[288U] = { 0U };
    uint64_t tmp1[9U] = { 0U };
    uint64_t *t0 = table;
    uint64_t *t1 = table + 9U;
    p521_make_fone(t0);
    memcpy(t1, tmp, 9U * sizeof(uint64_t));
    KRML_MAYBE_FOR15(i,
                     0U,
                     15U,
                     1U,
                     uint64_t *t11 = table + (i + 1U) * 9U;
                     fsqr0(tmp1, t11);
                     memcpy(table + (2U * i + 2U) * 9U, tmp1, 9U * sizeof(uint64_t));
                     uint64_t *t2 = table + (2U * i + 2U) * 9U;
                     fmul0(tmp1, tmp, t2);
                     memcpy(table + (2U * i + 3U) * 9U, tmp1, 9U * sizeof(uint64_t)););
    uint32_t i0 = 520U;
    uint64_t bits_c = Hacl_Bignum_Lib_bn_get_bits_u64(9U, b, i0, 5U);
    memcpy(res, (uint64_t *)table, 9U * sizeof(uint64_t));
    for (uint32_t i1 = 0U; i1 < 31U; i1++) {
        uint64_t c = FStar_UInt64_eq_mask(bits_c, (uint64_t)(i1 + 1U));
        const uint64_t *res_j = table + (i1 + 1U) * 9U;
        KRML_MAYBE_FOR9(i,
                        0U,
                        9U,
                        1U,
                        uint64_t *os = res;
                        uint64_t x = (c & res_j[i]) | (~c & res[i]);
                        os[i] = x;);
    }
    uint64_t tmp10[9U] = { 0U };
    for (uint32_t i1 = 0U; i1 < 104U; i1++) {
        KRML_MAYBE_FOR5(i, 0U, 5U, 1U, fsqr0(res, res););
        uint32_t k = 520U - 5U * i1 - 5U;
        uint64_t bits_l = Hacl_Bignum_Lib_bn_get_bits_u64(9U, b, k, 5U);
        memcpy(tmp10, (uint64_t *)table, 9U * sizeof(uint64_t));
        for (uint32_t i2 = 0U; i2 < 31U; i2++) {
            uint64_t c = FStar_UInt64_eq_mask(bits_l, (uint64_t)(i2 + 1U));
            const uint64_t *res_j = table + (i2 + 1U) * 9U;
            KRML_MAYBE_FOR9(i,
                            0U,
                            9U,
                            1U,
                            uint64_t *os = tmp10;
                            uint64_t x = (c & res_j[i]) | (~c & tmp10[i]);
                            os[i] = x;);
        }
        fmul0(res, res, tmp10);
    }
}

